using System;
using System.IO;
using System.Linq;
using System.Text;
using UnityEditor;
using UnityEngine;

namespace SplashEdit.EditorCode
{
    public class LicenseGeneratorWindow : EditorWindow
    {
        private DefaultAsset SelectedTmd;
        private string SelectedLicenseTextLineTop = "     Created wit        h       ";
        private string SelectedLicenseTextLineBottom = "                psxsplash       ";
        private LicenseGeneratorRegion SelectedLicenseGeneratorRegion = LicenseGeneratorRegion.None;

        bool? IsCustomLicenseGenerationOk = null;
        bool? IsRestorePsxSplashLicenseOk = null;

        [MenuItem("PlayStation 1/License Generator")]
        public static void ShowWindow()
        {
            // Creates and displays the window
            LicenseGeneratorWindow win = GetWindow<LicenseGeneratorWindow>("License Generator");
            win.minSize = new Vector2(450, 600);
        }

        private void OnGUI()
        {
            // Adds a label with the title
            GUILayout.Label("License Generator", PSXEditorStyles.WindowHeader);
            GUILayout.Label("This section allows you to generate and apply a customized license boot screen. This is the screen with the PSX logo and the SCEA/SCEE/SCEI license at the bottom", PSXEditorStyles.InfoBox);

            // <card>
            PSXEditorStyles.BeginCard();

            // The card header
            GUILayout.Label("Choose a .tmd file", PSXEditorStyles.CardHeaderStyle);

            // Choose a tmd file (not enforced here
            SelectedTmd = (DefaultAsset)EditorGUILayout.ObjectField("Tmd file", SelectedTmd, typeof(DefaultAsset), false);
            LicenseTmdValidationResult selectedTmdValidationResult = ValidateTmdAsset(SelectedTmd);

            // Show an error in case the selected Tmd isn't valid
            if (selectedTmdValidationResult != LicenseTmdValidationResult.Ok)
            {
                EditorGUILayout.BeginHorizontal(PSXEditorStyles.InfoBox);
                PSXEditorStyles.DrawStatusBadge("ERROR", PSXEditorStyles.Error);
                GUILayout.Label($"Invalid Tmd file ({selectedTmdValidationResult})", PSXEditorStyles.RichLabel);
                EditorGUILayout.EndHorizontal();
            }

            // </card>
            PSXEditorStyles.EndCard();

            #region Licensing text and region

            // <card>
            PSXEditorStyles.BeginCard();

            // The card header
            GUILayout.Label("Licensing text", PSXEditorStyles.CardHeaderStyle);
            GUILayout.Label("Use spaces to center the text manually", PSXEditorStyles.RichLabel);
            GUILayout.Label("Max 32 bytes per line.", PSXEditorStyles.RichLabel);
            GUILayout.Label("Avoid special characters outside the ASCII table", PSXEditorStyles.RichLabel);
            PSXEditorStyles.DrawSeparator(6, 6);

            // The first line of licensing
            SelectedLicenseTextLineTop = EditorGUILayout.TextField("First line", SelectedLicenseTextLineTop);
            LicenseTextValidationResult selectedLicenseTextLineTopValidationResult = ValidateLicenseTextLine(SelectedLicenseTextLineTop);
            if (selectedLicenseTextLineTopValidationResult != LicenseTextValidationResult.Ok)
            {
                EditorGUILayout.BeginHorizontal(PSXEditorStyles.InfoBox);
                PSXEditorStyles.DrawStatusBadge("ERROR", PSXEditorStyles.Error);
                GUILayout.Label($"The text is too long or uses invalid characters ({selectedLicenseTextLineTopValidationResult})", PSXEditorStyles.RichLabel);
                EditorGUILayout.EndHorizontal();
            }

            // The second line of licensing
            SelectedLicenseTextLineBottom = EditorGUILayout.TextField("Second line", SelectedLicenseTextLineBottom);
            LicenseTextValidationResult selectedLicenseTextLineBottomValidationResult = ValidateLicenseTextLine(SelectedLicenseTextLineBottom);
            if (selectedLicenseTextLineBottomValidationResult != LicenseTextValidationResult.Ok)
            {
                EditorGUILayout.BeginHorizontal(PSXEditorStyles.InfoBox);
                PSXEditorStyles.DrawStatusBadge("ERROR", PSXEditorStyles.Error);
                GUILayout.Label($"The text is too long or uses invalid characters ({selectedLicenseTextLineBottomValidationResult})", PSXEditorStyles.RichLabel);
                EditorGUILayout.EndHorizontal();
            }

            // Dropdown to select the region
            //SelectedLicenseGeneratorRegion = (LicenseGeneratorRegion)EditorGUILayout.EnumPopup("Region", SelectedLicenseGeneratorRegion);

            // </card>
            PSXEditorStyles.EndCard();

            #endregion

            #region Generation and errors

            // <card>
            PSXEditorStyles.BeginCard();

            GUILayout.Label("Generate and apply", PSXEditorStyles.CardHeaderStyle);
            GUILayout.Label("The \"Generate\" button will create (or overwrite) a file called customlicense.dat inside the Assets folder.", PSXEditorStyles.RichLabel);
            GUILayout.Label("It will also automatically update the \"License file\" setting inside the SplashEdit Control Panel", PSXEditorStyles.RichLabel);

            // Show the button to generate the customized SPLASHLICENSE.DAT only if everything seems ok
            if (selectedTmdValidationResult == LicenseTmdValidationResult.Ok && selectedLicenseTextLineTopValidationResult == LicenseTextValidationResult.Ok && selectedLicenseTextLineBottomValidationResult == LicenseTextValidationResult.Ok)
            {
                if (GUILayout.Button("Generate the custom license .dat file", PSXEditorStyles.PrimaryButton, GUILayout.Height(26)))
                {
                    IsCustomLicenseGenerationOk = null;
                    IsRestorePsxSplashLicenseOk = null;
                    IsCustomLicenseGenerationOk = GenerateLicenseDat();
                }

                if (IsCustomLicenseGenerationOk == true)
                {
                    EditorGUILayout.BeginHorizontal(PSXEditorStyles.InfoBox);
                    PSXEditorStyles.DrawStatusBadge("OK", PSXEditorStyles.Success);
                    GUILayout.Label($"Custom license applied", PSXEditorStyles.RichLabel);
                    EditorGUILayout.EndHorizontal();
                }
                else if (IsCustomLicenseGenerationOk == false)
                {
                    EditorGUILayout.BeginHorizontal(PSXEditorStyles.InfoBox);
                    PSXEditorStyles.DrawStatusBadge("ERROR", PSXEditorStyles.Error);
                    GUILayout.Label($"An error occured while trying to generate the custom license", PSXEditorStyles.RichLabel);
                    EditorGUILayout.EndHorizontal();
                }

                PSXEditorStyles.DrawSeparator(6, 6);
                GUILayout.Label("You can restore the original PsxSplash / SplashEdit license anytime you want", PSXEditorStyles.RichLabel);
                if (GUILayout.Button("Restore the original splashlicense.dat", PSXEditorStyles.SecondaryButton, GUILayout.Height(26)))
                {
                    IsCustomLicenseGenerationOk = null;
                    IsRestorePsxSplashLicenseOk = null;
                    SplashSettings.LicenseFilePath = SplashBuildPaths.DefaultLicenseFilePath;
                    IsRestorePsxSplashLicenseOk = true;
                }

                if (IsRestorePsxSplashLicenseOk == true)
                {
                    EditorGUILayout.BeginHorizontal(PSXEditorStyles.InfoBox);
                    PSXEditorStyles.DrawStatusBadge("OK", PSXEditorStyles.Success);
                    GUILayout.Label($"Splashlicense.dat restored", PSXEditorStyles.RichLabel);
                    EditorGUILayout.EndHorizontal();
                }
            }
            else
            {
                GUILayout.Label("The actions will reappear once all the errors are solved", PSXEditorStyles.InfoBox);
            }

            // </card>
            PSXEditorStyles.EndCard();

            #endregion 
        }

