0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00 };

            // Write the first 4 sectors: they're just the default sector 4 times
            for (int i = 0; i < 4; i++)
            {
                licensedatMemoryStream.Write(licensedatDefaultSectorBuffer, 0, licensedatDefaultSectorBuffer.Length);
            }

            var validateLicenseTextLineTop = ValidateLicenseTextLine(SelectedLicenseTextLineTop);
            var validateLicenseTextLineBottom = ValidateLicenseTextLine(SelectedLicenseTextLineBottom);

            // The 5th sector contains the licensing text
            if (validateLicenseTextLineTop == LicenseTextValidationResult.Ok && validateLicenseTextLineBottom == LicenseTextValidationResult.Ok)
            {
                // Create the buffer that will contain both lines of the license text
                byte[] licensedatTextBuffer = new byte[64] { 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20 };

                // Fill the buffer with both lines.
                Encoding.ASCII.GetBytes(SelectedLicenseTextLineTop, 0, SelectedLicenseTextLineTop.Length, licensedatTextBuffer, 0);
                Encoding.ASCII.GetBytes(SelectedLicenseTextLineBottom, 0, SelectedLicenseTextLineBottom.Length, licensedatTextBuffer, 32);

                // Clone the original default sector
                byte[] licensedatTextSectorBuffer = (byte[])licensedatDefaultSectorBuffer.Clone();

                // Write the text buffer from the 9th byte
                Buffer.BlockCopy(licensedatTextBuffer, 0, licensedatTextSectorBuffer, 8, licensedatTextBuffer.Length);

                // Write the sector buffer to the MemoryStream
                licensedatMemoryStream.Write(licensedatTextSectorBuffer, 0, licensedatTextSectorBuffer.Length);

                // Validate the Tmd
                var validationResult = ValidateTmdAsset(SelectedTmd);

                // Write the TMD
                if (validationResult == LicenseTmdValidationResult.Ok)
                {
                    // Open the TMD as a FileStream
                    string selectedTmdFilePath = AssetDatabase.GetAssetPath(SelectedTmd);
                    FileStream selectedTmdFileStream = new FileStream(selectedTmdFilePath, FileMode.Open, FileAccess.Read);

                    // We have 7 sectors to fill
                    for (int i = 0; i < 7; i++)
                    {
                        // Clone the default sector
                        byte[] tmdSectorBuffer = (byte[])licensedatDefaultSectorBuffer.Clone();

                        // Check if there's still some TMD left to write
                        if (selectedTmdFileStream.Length - selectedTmdFileStream.Position > 0)
                        {
                            // Get max 2048 bytes from the TMD
                            byte[] tmdPartialDataBuffer = new byte[Math.Min(selectedTmdFileStream.Length - selectedTmdFileStream.Position, 2048)];
                            selectedTmdFileStream.Read(tmdPartialDataBuffer, 0, tmdPartialDataBuffer.Length);

                            // Write the TMD partial data to the sector
                            Buffer.BlockCopy(tmdPartialDataBuffer, 0, tmdSectorBuffer, 8, tmdPartialDataBuffer.Length);
                        }

                        // Write the sector buffer to the MemoryStream
                        licensedatMemoryStream.Write(tmdSectorBuffer, 0, tmdSectorBuffer.Length);
                    }

                    selectedTmdFileStream.Close();

                    // Write the new customlicense.dat to the Assets directory
                    string assetPath = "Assets/customlicense.dat";
                    File.WriteAllBytes(assetPath, licensedatMemoryStream.ToArray());
                    AssetDatabase.ImportAsset(assetPath);

                    // Update the setting in the control panel
                    SplashSettings.LicenseFilePath = Path.GetFullPath(assetPath);

                }
                else
                {
                    isOK = false;
                }
            }
            else
            {
                isOK = false;
            }

            // Close the MemoryStream
            licensedatMemoryStream.Close();

            return isOK;
        }

        /// <summary>
        /// Does some checks to see if the string can be a valid license line for the PSX boot screen
        /// </summary>
        /// <param name="licenseLine"></param>
        /// <returns></returns>
        private LicenseTextValidationResult ValidateLicenseTextLine(string licenseLine)
        {
            LicenseTextValidationResult validationResult = LicenseTextValidationResult.Ok;
            if (Encoding.ASCII.GetByteCount(licenseLine) > 32)
            {
                validationResult = LicenseTextValidationResult.ErrorTooManyChars;
            }
            return validationResult;
        }

        /// <summary>
        /// Does some preliminary checks to see if the Asset is a valid TMD file, at least by type and size
        /// </summary>
        /// <returns></returns>
        private LicenseTmdValidationResult ValidateTmdAsset(DefaultAsset tmdAsset)
        {
            LicenseTmdValidationResult validationResult = LicenseTmdValidationResult.ErrorOther;

            // Check if the DefaultAsset is set
            if (tmdAsset != null)
            {
                // Get the path of the Asset
                string tmdFilePath = AssetDatabase.GetAssetPath(tmdAsset);

                // Check if the file exists
                if (File.Exists(tmdFilePath))
                {
                    // Open the Tmd as a FileStream
                    FileStream tmdFileStream = new FileStream(tmdFilePath, FileMode.Open, FileAccess.Read);

                    // We need a Tmd with at least its header and no more than 2048x7 bytes
                    if (tmdFileStream.Length > 12 && tmdFileStream.Length <= 14336)
                    {
                        // Get the signature of the Tmd file
                        byte[] tmdFileSignatureBuffer = new byte[12];
                        tmdFileStream.Read(tmdFileSignatureBuffer, 0, 12);

                        // Check for the validity of the signature
                        if (tmdFileSignatureBuffer.SequenceEqual(Tmd.MagicBytes))
                        {
                            // Everything seems ok
                            validationResult = LicenseTmdValidationResult.Ok;
                        }
                        else
                        {
                            validationResult = LicenseTmdValidationResult.ErrorInvalidTmdSignature;
                        }
                    }
                    else
                    {
                        validationResult = LicenseTmdValidationResult.ErrorBadTmdSize;
                    }
                }
                else
                {
                    validationResult = LicenseTmdValidationResult.ErrorMissingFile;
                }
            }
            else
            {
                validationResult = LicenseTmdValidationResult.ErrorMissingAsset;
            }
            return validationResult;
        }

        public enum LicenseTextValidationResult
        {
            Ok,
            ErrorOther,
            ErrorTooManyChars,
            ErrorWrongCharset
        }

        public enum LicenseTmdValidationResult
        {
            Ok,
            ErrorOther,
            ErrorMissingAsset,
            ErrorMissingFile,
            ErrorBadTmdSize,
            ErrorInvalidTmdSignature
        }

        public enum LicenseGeneratorRegion
        {
            America,
            Europe,
            Japan,
            None
        }

        public class Tmd
        {
            public static byte[] MagicBytes = { 0x41, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00 };
        }
    }


